package com.cashff.controller;

import com.cashff.dto.*; import com.cashff.entity.*; import com.cashff.repository.*; import com.cashff.service.CustomRoomSchedule;
import com.cashff.service.FileStorageService;
import jakarta.transaction.Transactional; import jakarta.validation.Valid; import org.springframework.http.MediaType; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile;
import java.time.*; import java.time.format.DateTimeFormatter; import java.util.*; import java.util.stream.Collectors;

@RestController @RequestMapping("/api/admin")
public class AdminController {
 private static final ZoneId IST = ZoneId.of("Asia/Kolkata");
 private final DonorSlotRepository donors; private final RedeemCodeRepository codes; private final CustomRoomRepository rooms; private final AppSettingRepository settings; private final DonationRepository donations; private final FileStorageService storage; private final CustomRoomSchedule roomSchedule;
 public AdminController(DonorSlotRepository donors,RedeemCodeRepository codes,CustomRoomRepository rooms,AppSettingRepository settings,DonationRepository donations,FileStorageService storage,CustomRoomSchedule roomSchedule){this.donors=donors;this.codes=codes;this.rooms=rooms;this.settings=settings;this.donations=donations;this.storage=storage;this.roomSchedule=roomSchedule;}
 @GetMapping("/donations") @Transactional public List<Map<String,Object>> donationDashboard(@RequestParam(name="startTime",required=false) String startTime,@RequestParam(name="endTime",required=false) String endTime,@RequestParam(name="sortBy",defaultValue="latest") String sortBy){Instant start=parseDate(startTime,false),end=parseDate(endTime,true);List<Donation> list=donations.findAll().stream().filter(d->start==null||!d.getUpdatedAt().isBefore(start)).filter(d->end==null||!d.getUpdatedAt().isAfter(end)).collect(Collectors.toCollection(ArrayList::new));Comparator<Donation> byAmount=Comparator.comparing(Donation::getTotalAmount);if("highToLow".equals(sortBy))list.sort(byAmount.reversed());else if("lowToHigh".equals(sortBy))list.sort(byAmount);else list.sort(Comparator.comparing(Donation::getUpdatedAt).reversed());return list.stream().map(this::donationMap).toList();}
 @DeleteMapping("/donations/{whatsapp}") public Map<String,String> deleteDonation(@PathVariable String whatsapp){donations.findByWhatsapp(whatsapp).ifPresent(donations::delete);return Map.of("message","Donation entry deleted.");}
 @PostMapping(value="/support/qr",consumes=MediaType.MULTIPART_FORM_DATA_VALUE) public Map<String,String> uploadQr(@RequestParam("image") MultipartFile image){String url=storage.storeImage(image);saveSetting("merchantQrUrl",url);return Map.of("message","Merchant QR updated.","qrUrl",url);}
 @GetMapping("/donor-slots") public Map<String,List<Map<String,Object>>> getDonors(){Map<String,List<Map<String,Object>>> out=new LinkedHashMap<>();for(String slot:List.of("9:00 AM","5:00 PM","9:00 PM"))out.put(slot,donors.findBySlotNameOrderByIdAsc(slot).stream().map(this::donorMap).toList());return out;}
 @PutMapping("/donor-slots/{slot}") @Transactional public Map<String,Object> updateDonorSlot(@PathVariable String slot,@RequestBody List<DonorInput> input){if(!List.of("9:00 AM","5:00 PM","9:00 PM").contains(slot))throw new IllegalArgumentException("Unknown time slot.");List<DonorSlot> existing=donors.findBySlotNameOrderByIdAsc(slot);String[] ranks={"1st","2nd","3rd"};for(int i=0;i<3;i++){DonorInput v=i<input.size()?input.get(i):null;DonorSlot row=i<existing.size()?existing.get(i):new DonorSlot();row.setSlotName(slot);row.setRankLabel(ranks[i]);row.setSupporterName(v==null||blank(v.name())?"Gamer":v.name());row.setAmount(v==null||blank(v.amount())?"₹100":v.amount());row.setType(v==null||blank(v.type())?"YouTube":v.type());row.setLink(v==null||blank(v.link())?"#":v.link());donors.save(row);}if(existing.size()>3)donors.deleteAll(existing.subList(3,existing.size()));return Map.of("message","Top supporters updated.","slot",slot);}
 @PostMapping("/redeem-codes") @Transactional public Map<String,Object> publishCodes(@Valid @RequestBody BulkCodesInput input){String codesText=input.codes();Instant now=Instant.now();Instant start=parseRequestInstant(input.startAt());Instant end=parseRequestInstant(input.endAt());if(blank(codesText))throw new IllegalArgumentException("Please enter at least one redeem code.");if(start==null||end==null)throw new IllegalArgumentException("Both start and end date-time fields are required.");if(start.isBefore(now))throw new IllegalArgumentException("Start time cannot be earlier than the current IST time.");if(!end.isAfter(start))throw new IllegalArgumentException("End time must be greater than the start time.");List<RedeemCode> saved=new ArrayList<>();for(String line:codesText.split("\\R")){String code=line.trim();if(!code.isEmpty())saved.add(codes.save(new RedeemCode(code,start,end)));}if(saved.isEmpty())throw new IllegalArgumentException("Enter at least one redeem code.");return Map.of("message","Redeem codes published.","count",saved.size());}
 @DeleteMapping("/redeem-codes") public Map<String,String> deleteAllCodes(){codes.deleteAll();return Map.of("message","All redeem codes deleted.");}
 @GetMapping("/rooms") public List<Map<String,Object>> allRooms(){return rooms.findAllByOrderByPublishedAtDesc().stream().map(roomSchedule::toAdminResponse).toList();}
 @PostMapping("/rooms") public Map<String,Object> addRoom(@Valid @RequestBody RoomInput input){CustomRoom room=roomSchedule.create(input.roomCode(),input.passwordCode(),input.startAt(),input.endAt());return roomSchedule.toAdminResponse(rooms.save(room));}
 @PutMapping("/rooms/{id}/schedule") @Transactional public Map<String,Object> scheduleLegacyRoom(@PathVariable Long id,@Valid @RequestBody RoomScheduleInput input){CustomRoom room=rooms.findById(id).orElseThrow(()->new IllegalArgumentException("Room not found."));roomSchedule.scheduleLegacy(room,input.startAt(),input.endAt());return roomSchedule.toAdminResponse(rooms.save(room));}
 @DeleteMapping("/rooms/{id}") public Map<String,String> deleteRoom(@PathVariable Long id){rooms.deleteById(id);return Map.of("message","Room deleted.");}
 @DeleteMapping("/rooms") public Map<String,String> deleteAllRooms(){rooms.deleteAll();return Map.of("message","All rooms deleted.");}
 @PostMapping(value="/rooms/{id}/photos",consumes=MediaType.MULTIPART_FORM_DATA_VALUE) @Transactional public Map<String,Object> uploadRoomPhotos(@PathVariable Long id,@RequestParam("p1") MultipartFile p1,@RequestParam("p2") MultipartFile p2,@RequestParam("p3") MultipartFile p3){CustomRoom r=rooms.findById(id).orElseThrow(()->new IllegalArgumentException("Room not found."));r.setFirstPhoto(storage.storeImage(p1));r.setSecondPhoto(storage.storeImage(p2));r.setThirdPhoto(storage.storeImage(p3));return roomSchedule.toAdminResponse(rooms.save(r));}
 @PostMapping(value="/banner",consumes=MediaType.MULTIPART_FORM_DATA_VALUE) public Map<String,String> uploadBanner(@RequestParam("image") MultipartFile image){String url=storage.storeImage(image);saveSetting("bannerUrl",url);return Map.of("message","Daily banner published.","bannerUrl",url);}
 @DeleteMapping("/banner") public Map<String,String> deleteBanner(){saveSetting("bannerUrl","");return Map.of("message","Daily banner deleted.");}
 private Map<String,Object> donorMap(DonorSlot d){return Map.of("rank",d.getRankLabel(),"name",d.getSupporterName(),"amount",d.getAmount(),"type",d.getType(),"link",d.getLink());}
 private Map<String,Object> donationMap(Donation d){List<Map<String,Object>> pics=d.getScreenshots().stream().map(s->Map.<String,Object>of("url",s.getImageUrl(),"createdAt",s.getCreatedAt().toString())).toList();Map<String,Object> m=new LinkedHashMap<>();m.put("whatsapp",d.getWhatsapp());m.put("amount",d.getTotalAmount());m.put("rawTime",d.getUpdatedAt().toString());m.put("timestamp",d.getUpdatedAt().toString());m.put("screenshots",pics);return m;}
 private void saveSetting(String key,String value){AppSetting setting=settings.findById(key).orElseGet(()->new AppSetting(key,value));setting.setSettingValue(value);settings.save(setting);}
 private boolean blank(String s){return s==null||s.isBlank();}
 private Instant parseDate(String value,boolean end){if(value==null||value.isBlank())return null;try{Instant instant;if(value.endsWith("Z")){instant=Instant.parse(value);}else if(value.matches(".*[+-][0-9]{2}:[0-9]{2}$")){instant=OffsetDateTime.parse(value).toInstant();}else{instant=OffsetDateTime.parse(value).toInstant();}return instant;}catch(Exception e){return null;}}
 private Instant parseRequestInstant(String value){if(blank(value))return null;String normalized=value.trim();try{if(normalized.endsWith("Z")){return Instant.parse(normalized);}if(normalized.matches(".*[+-][0-9]{2}:[0-9]{2}$")){return OffsetDateTime.parse(normalized).toInstant();}if(normalized.matches(".*[+-][0-9]{2}[0-9]{2}$")){return OffsetDateTime.parse(normalized.substring(0,normalized.length()-5)+normalized.substring(normalized.length()-5,normalized.length()-2)+":"+normalized.substring(normalized.length()-2),DateTimeFormatter.ISO_OFFSET_DATE_TIME).toInstant();}return LocalDateTime.parse(normalized,DateTimeFormatter.ISO_LOCAL_DATE_TIME).atZone(IST).toInstant();}catch(Exception e){throw new IllegalArgumentException("Invalid date-time value: " + value, e);}}
}
